import json

with open('/app/stats.json') as f:
    s = json.load(f)

dates = s['dates']
prices = s['prices']
annual_avg = s['annual_avg']
decade_stats = s['decade_stats']
rolling_vol = s['rolling_vol']
top_mom = s['top_mom_pct']
top_yoy = s['top_yoy']

# Prepare chart data
dates_js = json.dumps(dates)
prices_js = json.dumps(prices)

annual_years = json.dumps(list(annual_avg.keys()))
annual_vals = json.dumps(list(annual_avg.values()))

decade_labels = json.dumps([f"{d}s" for d in sorted(decade_stats.keys())])
decade_means = json.dumps([decade_stats[d]['mean'] for d in sorted(decade_stats.keys())])
decade_stds = json.dumps([decade_stats[d]['std'] for d in sorted(decade_stats.keys())])
decade_mins = json.dumps([decade_stats[d]['min'] for d in sorted(decade_stats.keys())])
decade_maxs = json.dumps([decade_stats[d]['max'] for d in sorted(decade_stats.keys())])

vol_dates = json.dumps([v['date'] for v in rolling_vol])
vol_vals = json.dumps([v['vol'] for v in rolling_vol])

# Distribution buckets
buckets = list(range(0, 145, 5))
hist_labels = [f"${b}-{b+5}" for b in buckets[:-1]]
hist_counts = [0] * (len(buckets) - 1)
for p in prices:
    for i in range(len(buckets) - 1):
        if buckets[i] <= p < buckets[i+1]:
            hist_counts[i] += 1
            break
    else:
        hist_counts[-1] += 1

hist_labels_js = json.dumps(hist_labels)
hist_counts_js = json.dumps(hist_counts)

# MoM % changes for chart
mom_pct_dates = []
mom_pct_vals = []
for i in range(1, len(prices)):
    pct = round(((prices[i] - prices[i-1]) / prices[i-1]) * 100, 2)
    mom_pct_dates.append(dates[i])
    mom_pct_vals.append(pct)

mom_dates_js = json.dumps(mom_pct_dates)
mom_vals_js = json.dumps(mom_pct_vals)

# Decade MoM volatility (std of MoM % changes per decade)
from collections import defaultdict
import math
decade_mom_pct = defaultdict(list)
for i in range(1, len(prices)):
    year = int(dates[i][:4])
    decade = (year // 10) * 10
    pct = ((prices[i] - prices[i-1]) / prices[i-1]) * 100
    decade_mom_pct[decade].append(pct)

decade_mom_vol = {}
for dec in sorted(decade_mom_pct.keys()):
    vals = decade_mom_pct[dec]
    m = sum(vals)/len(vals)
    v = sum((x-m)**2 for x in vals)/len(vals)
    decade_mom_vol[dec] = round(math.sqrt(v), 2)

decade_vol_labels = json.dumps([f"{d}s" for d in sorted(decade_mom_vol.keys())])
decade_vol_vals = json.dumps([decade_mom_vol[d] for d in sorted(decade_mom_vol.keys())])

# Key annotations for the main chart
annotations = [
    {"date": "1973-10-01", "label": "Arab Oil Embargo"},
    {"date": "1979-01-01", "label": "Iranian Revolution"},
    {"date": "1986-04-01", "label": "1986 Price Collapse"},
    {"date": "1990-08-01", "label": "Gulf War"},
    {"date": "1998-12-01", "label": "Asian Financial Crisis"},
    {"date": "2008-07-01", "label": "All-Time High ($132.83)"},
    {"date": "2008-12-01", "label": "Global Financial Crisis"},
    {"date": "2014-11-01", "label": "OPEC Market Share War"},
    {"date": "2020-04-01", "label": "COVID-19 Crash"},
    {"date": "2022-03-01", "label": "Russia-Ukraine War"},
]

# Top shocks table rows
shock_rows = ""
for m in top_mom[:12]:
    event = ""
    d = m['date']
    if d.startswith("1974-01"): event = "OPEC Oil Embargo"
    elif d.startswith("1973-10"): event = "Arab Oil Embargo Onset"
    elif d.startswith("1979-05"): event = "Iranian Revolution / Second Oil Crisis"
    elif d.startswith("1990-08"): event = "Iraqi Invasion of Kuwait"
    elif d.startswith("2020-05"): event = "Post-COVID Recovery Bounce"
    elif d.startswith("2020-03"): event = "COVID-19 Demand Shock"
    elif d.startswith("1986-08"): event = "Recovery from 1986 Collapse"
    elif d.startswith("2026-03"): event = "2026 Price Spike"
    elif d.startswith("1971-01"): event = "Tehran/Tripoli Agreement"
    elif d.startswith("2008-10"): event = "Global Financial Crisis"
    elif d.startswith("2008-11"): event = "Global Financial Crisis (cont.)"
    elif d.startswith("1986-02"): event = "Saudi Production Surge"
    else: event = "—"
    color = "color: #16a34a" if m['pct_change'] > 0 else "color: #dc2626"
    sign = "+" if m['pct_change'] > 0 else ""
    shock_rows += f"""<tr>
        <td>{d[:7]}</td>
        <td>${m['prev_price']:.2f}</td>
        <td>${m['price']:.2f}</td>
        <td style="{color}; font-weight:600">{sign}{m['pct_change']:.1f}%</td>
        <td style="{color}; font-weight:600">{sign}${m['change']:.2f}</td>
        <td>{event}</td>
    </tr>"""

# YoY table (deduplicate to unique events)
yoy_seen = set()
yoy_rows = ""
for y in top_yoy:
    yr = y['date'][:4]
    if yr in yoy_seen:
        continue
    yoy_seen.add(yr)
    event = ""
    if yr == "1974": event = "Post-Embargo Price Surge"
    elif yr == "1979" or yr == "1980": event = "Iranian Revolution / Iran-Iraq War"
    elif yr == "2009": event = "Post-GFC Recovery"
    elif yr == "1999": event = "Asian Crisis Recovery"
    elif yr == "2008": event = "Pre-Crisis Commodity Boom"
    else: event = "—"
    color = "color: #16a34a" if y['pct_change'] > 0 else "color: #dc2626"
    sign = "+" if y['pct_change'] > 0 else ""
    yoy_rows += f"""<tr>
        <td>{y['date'][:7]}</td>
        <td style="{color}; font-weight:600">{sign}{y['pct_change']:.1f}%</td>
        <td style="{color}; font-weight:600">{sign}${y['change']:.2f}</td>
        <td>{event}</td>
    </tr>"""

# Decade analysis paragraphs
decade_analysis = {
    "1970": {
        "title": "1970s — The End of Cheap Oil",
        "text": f"""The 1970s witnessed the most dramatic structural shift in crude oil history. Prices started at just $1.21/bbl in January 1970 and ended the decade above $39/bbl — a more than 30-fold increase. The decade's average price was ${decade_stats['1970']['mean']}/bbl with a standard deviation of ${decade_stats['1970']['std']}, reflecting enormous variance. Two defining events drove this transformation:<br><br>
<strong>1973 Arab Oil Embargo:</strong> OPEC's embargo against nations supporting Israel in the Yom Kippur War caused prices to jump from $2.70 to $4.10 (+52%) in October 1973, then to $13.00 (+217%) in January 1974 — the single largest percentage monthly increase in the dataset.<br><br>
<strong>1979 Iranian Revolution:</strong> The overthrow of the Shah disrupted Iranian supply, pushing prices from $14.50 in December 1978 to $40.75 by November 1979 — a 181% surge in under a year. This event established OPEC's pricing power and ended the era of sub-$10 oil for over a decade."""
    },
    "1980": {
        "title": "1980s — Boom, Bust, and the Counter-Shock",
        "text": f"""The 1980s averaged ${decade_stats['1980']['mean']}/bbl, making it the third-highest decade by mean price when adjusted for context. The decade opened with prices near $40 during the Iran-Iraq War period but experienced a dramatic collapse mid-decade.<br><br>
<strong>1980–1985 (Elevated Plateau):</strong> Prices held between $26–$40 as OPEC maintained production discipline and geopolitical instability persisted. The decade's high of ${decade_stats['1980']['max']}/bbl was recorded early in 1980.<br><br>
<strong>1986 Price Collapse:</strong> Saudi Arabia abandoned its swing producer role and flooded the market. Prices crashed from $26.50 in December 1985 to $9.62 in July 1986 — a 64% decline in seven months. This was the defining structural break of the decade, resetting oil markets for a generation. Prices never fully recovered to early-decade levels, closing the 1980s near $19/bbl."""
    },
    "1990": {
        "title": "1990s — Relative Stability and the Low-Price Era",
        "text": f"""The 1990s were the least volatile decade in the dataset, with a mean price of just ${decade_stats['1990']['mean']}/bbl and a standard deviation of only ${decade_stats['1990']['std']} — the lowest of any decade. This stability was disrupted only briefly:<br><br>
<strong>1990 Gulf War Spike:</strong> Iraq's invasion of Kuwait sent prices surging from $17.17 in July 1990 to $34.50 in October 1990 (+101%), before collapsing back to $18 by early 1991 as the coalition response restored market confidence.<br><br>
<strong>1997–1998 Asian Financial Crisis:</strong> Collapsing Asian demand pushed prices to the decade's low of ${decade_stats['1990']['min']}/bbl in December 1998. This period marked the bottom of a multi-year deflationary cycle in commodity markets and set the stage for the 2000s supercycle."""
    },
    "2000": {
        "title": "2000s — The Commodity Supercycle",
        "text": f"""The 2000s produced the most extreme price dynamics in the dataset. The decade's average was ${decade_stats['2000']['mean']}/bbl with a staggering standard deviation of ${decade_stats['2000']['std']} — both the highest volatility and the widest price range (${decade_stats['2000']['range']}) of any decade.<br><br>
<strong>2003–2008 Rally:</strong> Surging demand from China and emerging markets, combined with supply constraints and speculative flows, drove an unprecedented rally. Prices rose from roughly $25 in 2003 to the all-time high of $132.83 in July 2008 — a 430% increase in five years.<br><br>
<strong>2008 Crash:</strong> The Global Financial Crisis triggered the sharpest absolute decline in the dataset. From the July 2008 peak of $132.83, prices collapsed to $41.34 by December 2008 — a $91.49 drop (−69%) in just five months. The October 2008 single-month drop of −$26.96 was the largest absolute monthly decline ever recorded."""
    },
    "2010": {
        "title": "2010s — Peak Prices, Shale Revolution, and a New Order",
        "text": f"""The 2010s recorded the highest average price of any decade at ${decade_stats['2010']['mean']}/bbl, reflecting the first half's sustained high prices. However, the decade was split into two distinct regimes:<br><br>
<strong>2011–2014 (High Plateau):</strong> Brent-equivalent prices averaged above $100/bbl for four consecutive years (2011–2014), driven by the Arab Spring disruptions, sanctions on Iran, and steady global demand growth.<br><br>
<strong>2014–2016 Crash:</strong> OPEC's decision to defend market share rather than prices, combined with surging U.S. shale production, triggered a crash from $108/bbl in June 2014 to $29.78 in January 2016 — a 72% decline. Prices gradually recovered through 2017–2019 as OPEC+ production cuts took effect, ending the decade near $63/bbl."""
    },
    "2020": {
        "title": "2020s — Pandemic, Recovery, and Geopolitical Repricing",
        "text": f"""The 2020s (through March 2026) average ${decade_stats['2020']['mean']}/bbl with significant event-driven swings across a ${decade_stats['2020']['range']} range:<br><br>
<strong>2020 COVID-19 Crash:</strong> The pandemic-driven demand collapse pushed prices to $21.04 in April 2020 — the lowest level since 2002. This represented a 66% decline from January 2020 levels in just three months, one of the fastest drawdowns in history.<br><br>
<strong>2021–2022 Recovery and War Premium:</strong> Recovery demand and then Russia's invasion of Ukraine in February 2022 drove prices to $116.80 by June 2022 — a 455% recovery from the COVID low. Prices subsequently moderated through 2023–2025 as global growth slowed and supply adjusted, declining to $57.95 by December 2025 before a sharp spike to $87.84 in March 2026."""
    }
}

