          asia98: {{ type: 'line', xMin: 347, xMax: 347, borderColor: 'rgba(248,113,113,0.5)', borderWidth: 1, borderDash: [4,4], label: {{ display: true, content: 'Asian Crisis 1998', position: 'end', font: {{ size: 9 }}, color: '#f87171' }} }},
          peak08: {{ type: 'line', xMin: 462, xMax: 462, borderColor: 'rgba(74,222,128,0.5)', borderWidth: 1, borderDash: [4,4], label: {{ display: true, content: 'ATH $132.83 (Jul 2008)', position: 'start', font: {{ size: 9 }}, color: '#4ade80' }} }},
